using Aspire.Hosting.ApplicationModel;

var builder = DistributedApplication.CreateBuilder(args);

// Secrets
// A random JWT signing key is generated on first run and persisted in this project's user secrets
// (Parameters:jwt-key), so it never lives in source control. The API reads it as Jwt:Key (T08).
var jwtKey = builder.AddParameter(
    "jwt-key",
    new GenerateParameterDefault { MinLength = 64, Special = false },
    secret: true,
    persist: true);

// Database
// SQL Server container. The SA password is generated by Aspire and stored in user secrets.
// The data volume and persistent lifetime keep the database (and a fast startup) across runs.
var sql = builder.AddSqlServer("sql")
    .WithDataVolume("hero-registry-sql-data")
    .WithLifetime(ContainerLifetime.Persistent);

var database = sql.AddDatabase("HeroRegistryDb");

// API
// Receives ConnectionStrings__HeroRegistryDb through WithReference.
var api = builder.AddProject<Projects.HeroRegistry_Api>("api")
    .WithReference(database)
    .WaitFor(database)
    .WithEnvironment("Jwt__Key", jwtKey)
    .WithHttpHealthCheck("/health")
    .WithExternalHttpEndpoints()
    // Dashboard link straight to the interactive API reference (T02.1).
    .WithUrlForEndpoint("http", _ => new ResourceUrlAnnotation
    {
        Url = "/scalar",
        DisplayText = "Scalar API Reference",
    });

// UI
// Angular dev server (`npm start` runs `ng serve`) on its default port 4200, so the URL stays stable
// and matches the API's allowed CORS origin. proxy.conf.js forwards /api to the API endpoint
// that Aspire injects through WithReference (services__api__http__0).
builder.AddJavaScriptApp("ui", "../../../hero-registry-ui", "start")
    .WithNpm(install: true)
    .WithReference(api)
    .WaitFor(api)
    .WithHttpEndpoint(port: 4200, isProxied: false)
    .WithEnvironment("NG_CLI_ANALYTICS", "false")
    .WithExternalHttpEndpoints();

await builder.Build().RunAsync();
